def longest_common_substring(s1: str, s2: str) -> str:
    """Return the longest common substring of s1 and s2."""
    if not s1 or not s2:
        return ""

    m, n = len(s1), len(s2)
    # dp[i][j] = length of longest common substring ending at s1[i-1], s2[j-1]
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    max_len = 0
    end_idx = 0

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > max_len:
                    max_len = dp[i][j]
                    end_idx = i
            else:
                dp[i][j] = 0

    return s1[end_idx - max_len : end_idx]


def test_empty_strings():
    assert longest_common_substring("", "abc") == ""
    assert longest_common_substring("abc", "") == ""
    assert longest_common_substring("", "") == ""


def test_no_common():
    assert longest_common_substring("abc", "xyz") == ""


def test_identical():
    assert longest_common_substring("hello", "hello") == "hello"


def test_basic():
    assert longest_common_substring("abcdef", "zbcdf") == "bcd"


def test_multiple_same_length():
    # "abc" and "bcd" are both length 3; first found wins
    result = longest_common_substring("abcdex", "xbcdy")
    assert result == "bcd"


def test_single_char():
    assert longest_common_substring("a", "a") == "a"
    assert longest_common_substring("a", "b") == ""


def test_substring_at_start():
    assert longest_common_substring("programming", "program") == "program"


def test_substring_at_end():
    assert longest_common_substring("hello world", "the world") == " world"


